    threadId: fact.threadId,
    sourceType: 'fact' as const,
    horizonClass: !fact.effectiveTo ? 'timeless' as const : 'long-lived-context' as const,
    title: fact.factKey,
    anchorTime: fact.effectiveFrom,
    notes: [
      `factType=${fact.factType}`,
      `confidence=${fact.confidence}`,
    ],
  }));

